diff --git a/src/mcp-apps/_shared/openai-compat.ts b/src/mcp-apps/_shared/openai-compat.ts
index e769fdc1..de4d434e 100644
--- a/src/mcp-apps/_shared/openai-compat.ts
+++ b/src/mcp-apps/_shared/openai-compat.ts
@@ -1,107 +1,148 @@
 type UnknownRecord = Record<string, unknown>;

 const LOBU_VIEW_SNAPSHOT_KEY = "lobuViewSnapshot";
 const LOBU_VIEW_SNAPSHOT_VERSION = 1;

 export interface OpenAiCompatSnapshot<T> {
 	/** `undefined` means the host did not update this global. */
 	data: T | null | undefined;
 	/** `undefined` means the host did not update this global. */
 	approvalCapability: string | null | undefined;
 }

+function snapshotCapabilityFromMeta(meta: unknown): string | null {
+	if (!isStructuredObject(meta)) return null;
+	const token = meta["lobu/mcp-app-snapshot-capability"];
+	if (typeof token !== "string") return null;
+	const normalized = token.trim();
+	return normalized && normalized.length <= 512 ? normalized : null;
+}
+
 function isStructuredObject(value: unknown): value is UnknownRecord {
 	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
 }

 export function approvalCapabilityFromMeta(meta: unknown): string | null {
 	if (!isStructuredObject(meta)) return null;
 	const token = meta["lobu/approval-capability"];
 	return typeof token === "string" && token.length <= 4_096 ? token : null;
 }

 function approvalCapabilityFromResult(result: unknown): string | null {
 	if (!isStructuredObject(result)) return null;
 	return approvalCapabilityFromMeta(result._meta);
 }

+function snapshotCapabilityFromResult(result: unknown): string | null {
+	if (!isStructuredObject(result)) return null;
+	return snapshotCapabilityFromMeta(result._meta);
+}
+
+/** Read the opaque per-result restore key from ChatGPT compatibility globals. */
+export function snapshotCapabilityFromOpenAiGlobals(
+	globals: unknown,
+): string | null | undefined {
+	if (!isStructuredObject(globals)) return undefined;
+	const hasToolOutput = Object.hasOwn(globals, "toolOutput");
+	const hasFullToolResult =
+		hasToolOutput &&
+		isStructuredObject(globals.toolOutput) &&
+		Object.hasOwn(globals.toolOutput, "structuredContent");
+	const hasToolResponseMetadata = Object.hasOwn(
+		globals,
+		"toolResponseMetadata",
+	);
+	const metadata = isStructuredObject(globals.toolResponseMetadata)
+		? globals.toolResponseMetadata
+		: null;
+	if (hasToolResponseMetadata) {
+		return metadata
+			? (snapshotCapabilityFromResult(metadata.mcp_tool_result) ??
+					snapshotCapabilityFromResult(metadata.call_tool_result))
+			: null;
+	}
+	return hasFullToolResult
+		? snapshotCapabilityFromResult(globals.toolOutput)
+		: undefined;
+}
+
 function dataFromToolOutput<T>(toolOutput: unknown): T | null {
 	if (!isStructuredObject(toolOutput)) return null;
 	if (Object.hasOwn(toolOutput, "structuredContent")) {
 		return isStructuredObject(toolOutput.structuredContent)
 			? (toolOutput.structuredContent as T)
 			: null;
 	}
 	return toolOutput as T;
 }

 function dataFromWidgetState<T>(widgetState: unknown): T | null | undefined {
 	if (!isStructuredObject(widgetState)) return undefined;
 	const privateContent = widgetState.privateContent;
 	if (!isStructuredObject(privateContent)) return undefined;
 	const snapshot = privateContent[LOBU_VIEW_SNAPSHOT_KEY];
 	if (!isStructuredObject(snapshot)) return undefined;
 	if (snapshot.version !== LOBU_VIEW_SNAPSHOT_VERSION) return undefined;
 	return snapshot.data === null
 		? null
 		: isStructuredObject(snapshot.data)
 			? (snapshot.data as T)
 			: undefined;
 }

 function displaySafeSnapshotData<T>(data: T | null): T | null {
 	if (!isStructuredObject(data) || !Array.isArray(data.actions)) return data;
 	return {
 		...data,
 		actions: data.actions.filter(
 			(action) =>
 				!isStructuredObject(action) || action.tool !== "resolve_lobu_approval",
 		),
 	} as T;
 }

 /**
  * Cache the latest server-authored view in ChatGPT's per-widget UI state. The
  * snapshot is a display-only reload fallback; a fresh tool result always wins.
  * Hidden result metadata is deliberately excluded.
  */
 export function persistOpenAiViewSnapshot<T>(
 	globals: unknown,
 	data: T | null,
 ): boolean {
 	if (!isStructuredObject(globals)) return false;
 	const setWidgetState = globals.setWidgetState;
 	if (typeof setWidgetState !== "function") return false;

 	const widgetState = isStructuredObject(globals.widgetState)
 		? globals.widgetState
 		: {};
 	const privateContent = isStructuredObject(widgetState.privateContent)
 		? widgetState.privateContent
 		: {};
 	const nextWidgetState = {
 		...widgetState,
 		privateContent: {
 			...privateContent,
 			[LOBU_VIEW_SNAPSHOT_KEY]: {
 				version: LOBU_VIEW_SNAPSHOT_VERSION,
 				data: displaySafeSnapshotData(data),
 			},
 		},
